import DomainLayer
import Foundation

/// Bundled province outlines and municipalities (generated by `Tools/generate_geography.py`
/// from the ministry's own station coordinates). Immutable once loaded.
struct GeographyStore: Sendable {
    let provinces: [Province]
    let municipalities: [Municipality]

    init(provinces: [Province], municipalities: [Municipality]) {
        self.provinces = provinces
        self.municipalities = municipalities
    }

    static func bundled() -> GeographyStore {
        let decoder = JSONDecoder()
        let provinceDTOs = load([BundledProvinceDTO].self, named: "provinces", decoder: decoder) ?? []
        let municipalityDTOs = load([BundledMunicipalityDTO].self, named: "municipalities", decoder: decoder) ?? []
        let provinces = provinceDTOs.map { dto in
            Province(
                id: ProvinceID(dto.id),
                name: TextNormalizer.name(dto.name),
                regionID: dto.regionID,
                bounds: BoundingBox(minLatitude: dto.bounds[0], minLongitude: dto.bounds[1],
                                    maxLatitude: dto.bounds[2], maxLongitude: dto.bounds[3]),
                outline: dto.hull.map { Coordinate(latitude: $0[0], longitude: $0[1]) },
                samples: dto.samples.map { Coordinate(latitude: $0[0], longitude: $0[1]) }
            )
        }
        let municipalities = municipalityDTOs.map {
            Municipality(id: MunicipalityID($0.id), name: TextNormalizer.name($0.name), provinceID: ProvinceID($0.provinceID))
        }
        return GeographyStore(provinces: provinces, municipalities: municipalities)
    }

    private static func load<T: Decodable>(_ type: T.Type, named name: String, decoder: JSONDecoder) -> T? {
        guard let url = Bundle.module.url(forResource: name, withExtension: "json"),
              let data = try? Foundation.Data(contentsOf: url) else { return nil }
        return try? decoder.decode(T.self, from: data)
    }

    /// Province containing the point. Where outlines overlap (they're convex hulls), or the point is
    /// just outside every outline (coast, borders), the province of the nearest sample station wins.
    func province(at point: Coordinate) -> ProvinceID? {
        let inside = provinces.filter { $0.bounds.contains(point) && Self.polygon($0.outline, contains: point) }
        if inside.count == 1 { return inside[0].id }
        let candidates = inside.isEmpty ? provinces.filter { $0.bounds.expanded(by: 0.5).contains(point) } : inside
        return candidates
            .compactMap { province in province.samples.map { $0.distance(to: point) }.min().map { (province.id, $0) } }
            .min { $0.1 < $1.1 }?.0
    }

    func provinces(intersecting box: BoundingBox) -> [ProvinceID] {
        provinces.filter { province in
            guard province.bounds.intersects(box) else { return false }
            // Cheap checks first: a sample station or outline vertex inside the box.
            if province.samples.contains(where: box.contains) || province.outline.contains(where: box.contains) { return true }
            // The box sits entirely inside the outline.
            let corners = [
                Coordinate(latitude: box.minLatitude, longitude: box.minLongitude),
                Coordinate(latitude: box.minLatitude, longitude: box.maxLongitude),
                Coordinate(latitude: box.maxLatitude, longitude: box.minLongitude),
                Coordinate(latitude: box.maxLatitude, longitude: box.maxLongitude),
            ]
            return corners.contains { Self.polygon(province.outline, contains: $0) }
        }.map(\.id)
    }

    func municipalities(matching text: String) -> [Municipality] {
        let needle = Self.fold(text)
        guard !needle.isEmpty else { return [] }
        return municipalities
            .filter { Self.fold($0.name).contains(needle) }
            .sorted { lhs, rhs in
                // Names that start with the search text come first.
                let l = Self.fold(lhs.name).hasPrefix(needle), r = Self.fold(rhs.name).hasPrefix(needle)
                return l != r ? l : lhs.name < rhs.name
            }
    }

    /// Case- and accent-insensitive form for matching ("Ávila" ~ "avila").
    static func fold(_ text: String) -> String {
        text.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "es_ES"))
            .trimmingCharacters(in: .whitespaces)
    }

    /// Ray-casting point-in-polygon test.
    static func polygon(_ vertices: [Coordinate], contains point: Coordinate) -> Bool {
        guard vertices.count >= 3 else { return false }
        var inside = false
        var j = vertices.count - 1
        for i in vertices.indices {
            let a = vertices[i], b = vertices[j]
            if (a.longitude > point.longitude) != (b.longitude > point.longitude),
               point.latitude < (b.latitude - a.latitude) * (point.longitude - a.longitude) / (b.longitude - a.longitude) + a.latitude {
                inside.toggle()
            }
            j = i
        }
        return inside
    }
}
